25		/** Stretch 모드가 기대하는 메시는 단위 정육면체다 — scale = size / 이 값 */
26		constexpr float UnitCube = 100.f;
27	
28		/**
29		 * 타일링 보정 배율이 이 범위를 벗어나면 그 조각은 그 발자국에 안 맞는 것이다.
30		 * 세우기는 하되 로그로 알린다 — 팩을 갈아 끼웠을 때 격자 치수를 그 팩 모듈에
31		 * 맞춰 다시 잡으라는 신호다 (docs/systems/asset-swap.md).
32		 */
33		constexpr float TileFitMin = 0.85f;
34		constexpr float TileFitMax = 1.15f;
35	
36		/**
37		 * 변형을 자리 좌표로 고른다. 난수 스트림을 쓰면 호출 순서에 의존해서 머신마다
38		 * 갈릴 수 있는데, 좌표 해시는 순서와 무관하게 모든 머신에서 같은 값이 나온다.
39		 */
40		int32 PickVariant(const FVector& Spot, int32 Count)
41		{
42			if (Count <= 1)
43			{
44				return 0;
45			}
46			uint32 Hash = 2166136261u;
47			for (int32 Axis = 0; Axis < 3; ++Axis)
48			{
49				const uint32 Value = static_cast<uint32>(FMath::RoundToInt(Spot[Axis] * 0.1f));
50				for (int32 Byte = 0; Byte < 4; ++Byte)
51				{
52					Hash ^= (Value >> (Byte * 8)) & 0xFF;
53					Hash *= 16777619u;
54				}
55			}
56			return static_cast<int32>(Hash % static_cast<uint32>(Count));
57		}
58	
59		/**
60		 * 발자국을 조각 자연 크기로 채우는 칸들을 만든다 — 긴 축으로 늘어놓고 높이
61		 * 축으로 쌓는다. 나머지 길이는 장수로 나눠 흡수하고, 남는 높이는 맨 윗단이
62		 * 받는다(눈이 가는 아래쪽 비율을 지키는 편이 전체를 눌러 놓는 것보다 낫다).
63		 * 두께 축은 칸을 그대로 두고, 조각을 앉힐 때 늘리지 않는다.
64		 */
65		void MakeTileCells(const FBox2D& Rect, float Base, float Top, const FVector& PieceSize, bool& bOutRunAlongX, TArray<FBox>& OutCells)
66		{
67			const FVector2D Size = Rect.GetSize();
68			bOutRunAlongX = Size.X >= Size.Y;
69	
70			const float Run = bOutRunAlongX ? Size.X : Size.Y;
71			const float PieceRun = FMath::Max(FMath::Max(PieceSize.X, PieceSize.Y), 1.f);
72			const int32 Count = FMath::Max(1, FMath::RoundToInt(Run / PieceRun));
73			const float CellRun = Run / Count;
74	
75			const float PieceHeight = FMath::Max(PieceSize.Z, 1.f);
76			const float Height = Top - Base;
77			const int32 Rows = FMath::Max(1, FMath::RoundToInt(Height / PieceHeight));
78			const float TopHeight = Height - (Rows - 1) * PieceHeight;
79	
80			for (int32 Row = 0; Row < Rows; ++Row)
81			{
82				const float RowBase = Base + Row * PieceHeight;
83				const float RowHeight = Row == Rows - 1 ? TopHeight : PieceHeight;
84				for (int32 Index = 0; Index < Count; ++Index)
85				{
86					const float RunMin = (bOutRunAlongX ? Rect.Min.X : Rect.Min.Y) + Index * CellRun;
87					const FVector2D CellMin = bOutRunAlongX ? FVector2D(RunMin, Rect.Min.Y) : FVector2D(Rect.Min.X, RunMin);
88					const FVector2D CellMax = bOutRunAlongX ? FVector2D(RunMin + CellRun, Rect.Max.Y) : FVector2D(Rect.Max.X, RunMin + CellRun);
89					OutCells.Add(FBox(FVector(CellMin.X, CellMin.Y, RowBase), FVector(CellMax.X, CellMax.Y, RowBase + RowHeight)));
90				}
91			}
92		}
93	
94		/**
95		 * 조각 하나를 칸에 앉힌다. 길이와 높이는 칸에 맞추고, **두께는 늘리지 않고**
96		 * 칸 가운데에 세운다 — 발자국의 두께는 비워 둔 공간이지 채워야 할 부피가
97		 * 아니다. 피벗은 메시 바운드 중심으로 보정하므로 조각의 원점이 어디에 있든
98		 * 상관없다. 반환값은 길이 축 보정 배율이다.
99		 */
100		float FitPieceToCell(const FBox& Cell, const FBox& Bounds, bool bRunAlongX, FTransform& OutInstance)
101		{
102			const FVector MeshSize = Bounds.GetSize();
103			const bool bMeshRunAlongX = MeshSize.X >= MeshSize.Y;
104			const float MeshRun = FMath::Max(FMath::Max(MeshSize.X, MeshSize.Y), 1.f);
105			const float MeshHeight = FMath::Max(MeshSize.Z, 1.f);
106	
107			const FVector CellSize = Cell.GetSize();
108			const float RunScale = (bRunAlongX ? CellSize.X : CellSize.Y) / MeshRun;
109			const float HeightScale = CellSize.Z / MeshHeight;
110	
111			const FVector Scale = bMeshRunAlongX ? FVector(RunScale, 1.f, HeightScale) : FVector(1.f, RunScale, HeightScale);
112			const FQuat Rotation = FRotator(0.f, bRunAlongX == bMeshRunAlongX ? 0.f : 90.f, 0.f).Quaternion();
113	
114			OutInstance.SetRotation(Rotation);
115			OutInstance.SetScale3D(Scale);
116			OutInstance.SetLocation(Cell.GetCenter() - Rotation.RotateVector(Scale * Bounds.GetCenter()));
117			return RunScale;
118		}
119	
120		/** 조각 표에서 이 자리에 쓸 변형 하나를 꺼낸다 */
121		UStaticMesh* PickMesh(const UCL9PieceDef& Piece, const FVector& Spot)
122		{
123			const int32 Index = PickVariant(Spot, Piece.Variants.Num());
124			return Piece.Variants[Index].LoadSynchronous();
125		}
126	
127		/** 타일링한 종류마다 한 줄씩 남기는 맞춤 기록 — 팩을 갈아 끼웠을 때 이걸 본다 */
128		struct FTileReport
129		{
130			FVector PieceSize = FVector::ZeroVector;
131			int32 Tiles = 0;
132			float WorstRunFit = 1.f;
133			/** Grid 종류는 계단실 띠처럼 짧은 발자국이 늘 있어 경고를 내지 않는다 — 기록만 남긴다 */
134			bool bWarnOnFit = true;
135	
136			void Note(float Fit)
137			{
138				if (FMath::Abs(Fit - 1.f) > FMath::Abs(WorstRunFit - 1.f))
139				{
140					WorstRunFit = Fit;
141				}
142			}
143		};
144	
145		/** 그 종류가 쓰는 조각의 첫 변형 메시 — 실측 치수를 재려고 꺼낸다 */
146		const UStaticMesh* LeadMesh(const UCL9DefRegistry& Registry, FName KindName, FName Theme)
147		{
148			const UCL9SegKindDef* Kind = Registry.FindSegKind(KindName);
149			const UCL9PieceDef* Piece = Kind != nullptr ? Registry.FindPiece(Kind->Piece, Theme) : nullptr;
150			return (Piece != nullptr && Piece->Variants.Num() > 0) ? Piece->Variants[0].LoadSynchronous() : nullptr;
151		}
152	}
