328		int32 RotateSide(int32 Side, int32 Rotation);
329	
330		/** 칸의 그 변(N=0·E=1·S=2·W=3) 상태 */
331		ECL9GridEdge EdgeOfCell(const FCL9SiteLayout& Layout, int32 Floor, FIntPoint Cell, int32 Side);
332	
333		/**
334		 * 그 용도로 쓸 수 있는 지점들의 인덱스를, **시작 모듈에서 먼 것부터** 담는다
335		 * (module.md 결정 4). 몬스터는 앞쪽에서, 재료는 전체에서 고르면 "깊이 들어갈수록
336		 * 위험하다"가 배치만으로 성립한다.
337		 */
338		void PointsOfPurpose(const FCL9SiteLayout& Layout, ECL9PointPurpose Purpose, TArray<int32>& OutIndices);
339	
340		/**
341		 * 깊이 = 홉 거리 ÷ 판에서 가장 먼 홉(0이 입구, 1이 가장 깊은 곳). PointsOfPurpose 중 깊이가 [DepthMin, DepthMax) 띠에 드는 것만 (먼 것부터). DepthMax가 1이면
342		 * 가장 깊은 지점까지 넣는다 — 사이트 구역(UCL9SiteDef::Zones)이 이 띠로 스폰 자리를 나눈다.
343		 */
344		void PointsInDepthBand(const FCL9SiteLayout& Layout, ECL9PointPurpose Purpose, float DepthMin, float DepthMax, TArray<int32>& OutIndices);
345	
346		/** 문만으로 모든 모듈이 서로 도달 가능하면 true */
347		bool IsConnected(const FCL9SiteLayout& Layout);
348	
349		/** 배치 바이트에 대한 FNV-1a 해시 — 모든 머신에서 로그로 남겨서 불일치가 생기면 값이 서로 달라져 드러난다 */
350		uint32 LayoutHash(const FCL9SiteLayout& Layout);
351	}
352

