87		{
88			int32 Count = 0;
89			for (uint8 Edge : Layout.EdgeX)
90			{
91				Count += (Edge == static_cast<uint8>(State)) ? 1 : 0;
92			}
93			for (uint8 Edge : Layout.EdgeY)
94			{
95				Count += (Edge == static_cast<uint8>(State)) ? 1 : 0;
96			}
