132	IMPLEMENT_SIMPLE_AUTOMATION_TEST(FCL9SiteLayoutAssemblyTest,
133		"CL9.Map.Assembly",
134		EAutomationTestFlags::EditorContext | EAutomationTestFlags::ProductFilter)
135	
136	bool FCL9SiteLayoutAssemblyTest::RunTest(const FString& Parameters)
137	{
138		const FTestModules Modules;
139		FCL9SiteParams Params;
140		Params.Theme = TEXT("henhouse");
141	
142		int32 Disconnected = 0;
143		int32 Overlapped = 0;
144		int32 NoExit = 0;
145		int32 Undersized = 0;
146		int32 Smallest = MAX_int32;
147		int32 Largest = 0;
148		float Total = 0.f;
149		float DeadEnds = 0.f;
150		float Loops = 0.f;
151		int32 Runs = 0;
152	
153		for (uint32 Seed = 1; Seed <= 200; ++Seed)
154		{
155			const FCL9SiteLayout Layout = CL9SiteLayout::Generate(Params, Modules.Defs, Seed);
156			if (!Layout.bBuilt)
157			{
158				++Undersized;
159				continue;
160			}
161	
162			if (!CL9SiteLayout::IsConnected(Layout))
163			{
164				++Disconnected;
165			}
166	
167			int32 Expected = 0;
168			for (const FCL9ModulePlacement& Module : Layout.Modules)
169			{
170				Expected += Module.Size.X * Module.Size.Y;
171			}
172			if (Expected != CountOccupiedCells(Layout))
173			{
174				++Overlapped;
175			}
176	
177			// 비상구는 정확히 하나다 (module.md 결정 3)
178			if (CountEdges(Layout, ECL9GridEdge::Flap) != 1)
179			{
180				++NoExit;
181			}
182	
183			Smallest = FMath::Min(Smallest, Layout.Modules.Num());
184			Largest = FMath::Max(Largest, Layout.Modules.Num());
185			Total += Layout.Modules.Num();
186			for (const FCL9ModulePlacement& Module : Layout.Modules)
187			{
188				DeadEnds += Module.Def->Type == ECL9ModuleType::DeadEnd ? 1 : 0;
189			}
190			Loops += CountEdges(Layout, ECL9GridEdge::Door) - (Layout.Modules.Num() - 1) - 1;
191			++Runs;
192		}
193	
194		// 크기와 모양은 통과·실패로 나누기 어렵고 값을 보면서 손잡이를 돌려야 한다 — 숫자를 남긴다
195		AddInfo(FString::Printf(TEXT("%d runs: %d~%d modules (avg %.1f of a wanted %d), %.0f%% dead ends, %.1f loop doors per run."),
196			Runs, Smallest, Largest, Total / FMath::Max(Runs, 1), Params.ModuleCount,
197			100.f * DeadEnds / FMath::Max(Total, 1.f), Loops / FMath::Max(Runs, 1)));
198	
199		TestEqual(TEXT("every module is reachable through doors"), Disconnected, 0);
200		TestEqual(TEXT("no two modules share a cell"), Overlapped, 0);
201		TestEqual(TEXT("exactly one emergency exit per run"), NoExit, 0);
202		TestEqual(TEXT("every seed builds"), Undersized, 0);
203		// 프론티어가 일찍 마르면 판이 확 작아진다 — 목표의 절반은 넘어야 한 판이라 할 수 있다
204		TestTrue(FString::Printf(TEXT("the smallest run had %d modules of a wanted %d"), Smallest, Params.ModuleCount),
205			Smallest >= Params.ModuleCount / 2);
206		return true;
207	}
