222	
223		const FCL9SiteLayout Layout = CL9SiteLayout::Generate(Params, Modules.Defs, 873);
224		CL9SiteLayout::BuildSegments(Params, Layout, Segs);
225	
226		TMap<FName, int32> ByKind;
227		for (const FCL9SiteSeg& Seg : Segs)
228		{
229			++ByKind.FindOrAdd(Seg.Kind);
230			TestTrue(TEXT("every box has area"), Seg.Rect.GetSize().X > 0.f && Seg.Rect.GetSize().Y > 0.f);
231		}
232	
233		// 바닥은 모듈마다 한 장 — 실내는 floor, 마당은 yard — 이고, 천장은 야외 모듈을 뺀 만큼이다
234		int32 Indoor = 0;
235		for (const FCL9ModulePlacement& Module : Layout.Modules)
236		{
237			Indoor += Module.Def->bOutdoor ? 0 : 1;
238		}
