240		TestEqual(TEXT("yards only under outdoor modules"), ByKind.FindRef(CL9SegKind::Yard()), Layout.Modules.Num() - Indoor);
241		TestEqual(TEXT("one ceiling per indoor module"), ByKind.FindRef(CL9SegKind::Ceiling()), Indoor);
242	
243		// 문 양옆 토막은 온전한 벽과 종류가 다르다 — 문마다 둘씩
244		TestEqual(TEXT("two stubs per doorway"), ByKind.FindRef(CL9SegKind::BarnStub()) + ByKind.FindRef(CL9SegKind::WallStub()),
245			2 * (ByKind.FindRef(CL9SegKind::Door()) + ByKind.FindRef(CL9SegKind::FlapIn())));
246	
247		// 천장 스위치를 끄면 천장만 사라지고 바닥·벽은 그대로다 (site.md bBuildCeilings)
248		{
249			FCL9SiteParams NoCeiling = Params;
250			NoCeiling.bBuildCeilings = false;
251			TArray<FCL9SiteSeg> Bare;
252			CL9SiteLayout::BuildSegments(NoCeiling, Layout, Bare);
253			int32 Ceilings = 0;
254			int32 Floors = 0;
255			for (const FCL9SiteSeg& Seg : Bare)
256			{
257				Ceilings += Seg.Kind == CL9SegKind::Ceiling() ? 1 : 0;
258				Floors += Seg.Kind == CL9SegKind::Floor() ? 1 : 0;
259			}
260			TestEqual(TEXT("ceilings off means no ceiling boxes"), Ceilings, 0);
261			TestEqual(TEXT("ceilings off leaves the floors alone"), Floors, ByKind.FindRef(CL9SegKind::Floor()));
262		}
263		TestEqual(TEXT("one emergency exit"), ByKind.FindRef(CL9SegKind::FlapIn()), 1);
264		TestTrue(TEXT("the outer wall is sealed"), ByKind.FindRef(CL9SegKind::Barn()) + ByKind.FindRef(CL9SegKind::Wall()) > 0);
265		// 입구 하나 + 모듈을 이은 문들 (module.md 결정 3)
266		TestTrue(TEXT("there are doorways"), ByKind.FindRef(CL9SegKind::Door()) >= Layout.Modules.Num());
267	
268		// 소품이 모듈을 따라 도는 변환은 소켓 회전과 같은 뜻이어야 한다 — 회전 전 East 변의
269		// 한가운데 점이 회전 r 뒤 RotateSide(East, r) 변의 한가운데로 가야 한다.
270		{
271			FCL9ModulePlacement Module;
272			Module.Def = Modules.Defs[4]; // coop_hall 3×3
273			Module.Origin = FIntPoint(2, 1);
274			const FVector2D Cell(Params.CellSize, Params.CellSize);
275			for (int32 Rotation = 0; Rotation < 4; ++Rotation)
276			{
277				Module.Rotation = Rotation;
278				Module.Size = UCL9ModuleDef::RotateSize(Module.Def->Size, Rotation);
279				const FVector2D Min = Layout.Origin + FVector2D(Module.Origin.X, Module.Origin.Y) * Cell;
280				const FVector2D Max = Min + FVector2D(Module.Size.X, Module.Size.Y) * Cell;
281				const FVector2D Mid = (Min + Max) * 0.5f;
282				const FVector2D EastMid(Module.Def->Size.X * Params.CellSize, Module.Def->Size.Y * Params.CellSize * 0.5f);
283				const FVector2D Moved = CL9SiteLayout::ModuleLocalToSite(Params, Layout, Module, EastMid);
284				const int32 Side = CL9SiteLayout::RotateSide(/*East*/ 1, Rotation);
285				const FVector2D Expected = Side == 0 ? FVector2D(Mid.X, Max.Y) : Side == 1 ? FVector2D(Max.X, Mid.Y)
286					: Side == 2 ? FVector2D(Mid.X, Min.Y) : FVector2D(Min.X, Mid.Y);
287				TestTrue(FString::Printf(TEXT("module-local East midpoint follows rotation %d"), Rotation), Moved.Equals(Expected, 1.f));
288				// 같은 회전으로 소켓을 돌리면 그 변만 켜져 있어야 한다
289				const uint8 Sockets = UCL9ModuleDef::RotateSockets(static_cast<uint8>(SockE), Rotation);
290				TestEqual(FString::Printf(TEXT("RotateSide agrees with RotateSockets at %d"), Rotation), static_cast<int32>(Sockets), 1 << Side);
291			}
292		}
293	
294		// 디딤판은 바닥처럼 기준점 아래로 자라는 종류이고, 위쪽 면이 계단 곡선을 따라야 한다
295		{
296			const float Storey = FMath::Max(Params.FloorHeight, 1.f);
297			for (const FCL9SiteSeg& Seg : Segs)
298			{
299				if (Seg.Kind != CL9SegKind::Tread())
300				{
301					continue;
302				}
303				TestTrue(TEXT("tread kind grows down"), CL9SegKind::GrowsDown(Seg.Kind));
304				const float Rel = FMath::Fmod(Seg.BaseZ, Storey);
305				TestTrue(TEXT("tread top sits between the floors"), Seg.BaseZ > 0.f && (Rel > 1.f || FMath::IsNearlyEqual(Rel, 0.f, 1.f)));
306			}
307		}
308	
309		// 지점은 배치된 칸 수를 넘지 않는다 — 용도가 0인 모듈은 지점을 안 낸다
310		TestTrue(TEXT("points do not outnumber cells"), Layout.Points.Num() <= CountOccupiedCells(Layout));
311	
312		TArray<int32> Jars;
313		CL9SiteLayout::PointsOfPurpose(Layout, ECL9PointPurpose::Jar, Jars);
314		TestTrue(TEXT("the delivery room offers a jar spot"), Jars.Num() > 0);
315	
316		TArray<int32> MonsterPoints;
317		CL9SiteLayout::PointsOfPurpose(Layout, ECL9PointPurpose::Monster, MonsterPoints);
318		TestTrue(TEXT("monster spots are sorted deepest first"),
319			MonsterPoints.Num() < 2 || Layout.Points[MonsterPoints[0]].Hops >= Layout.Points[MonsterPoints.Last()].Hops);
320		return true;
321	}
