323	IMPLEMENT_SIMPLE_AUTOMATION_TEST(FCL9SiteLayoutFloorsTest,
324		"CL9.Map.Floors",
325		EAutomationTestFlags::EditorContext | EAutomationTestFlags::ProductFilter)
326	
327	bool FCL9SiteLayoutFloorsTest::RunTest(const FString& Parameters)
328	{
329		const FTestModules Modules;
330		FCL9SiteParams Params;
331		Params.Theme = TEXT("henhouse");
332	
333		// 계단 모듈이 한 행도 없으면 층이 몇이든 단층이어야 한다 — 올라갈 길이 없으니까.
334		{
335			FCL9SiteParams Tall = Params;
336			Tall.MaxFloors = 3;
337			TArray<const UCL9ModuleDef*> NoStairs = Modules.Defs;
338			NoStairs.RemoveAll([](const UCL9ModuleDef* Def) { return Def->Type == ECL9ModuleType::Stair; });
339			TestEqual(TEXT("no stair row means one floor"), CL9SiteLayout::Generate(Tall, NoStairs, 873).FloorCount, 1);
340		}
341	
342		// MaxFloors 1은 예전 그대로여야 한다 — 층을 넣었다고 단층 판이 달라지면 회귀다.
343		TestEqual(TEXT("MaxFloors 1 stays single-storey"),
344			CL9SiteLayout::Generate(Params, Modules.Defs, 873).FloorCount, 1);
345	
346		Params.MaxFloors = 3;
347		Params.StairCountMin = 2;
348		Params.StairCountMax = 4;
349	
350		int32 Disconnected = 0;
351		int32 Overlapped = 0;
352		int32 Unsupported = 0;
353		int32 Floating = 0;
354		int32 Stranded = 0;
355		int32 TwoOrMore = 0;
356		int32 ThreeFloors = 0;
357		float Stairs = 0.f;
358		float Upstairs = 0.f;
359		float ReachSum = 0.f;
360		int32 Runs = 0;
361	
362		// 계단 위층에서 **내려오지 않고** 문만으로 닿는 모듈 수 — 계단 자신은 빼고 센다
363		auto UpperReach = [](const FCL9SiteLayout& Layout, int32 StairIndex)
364		{
365			const int32 Upper = Layout.Modules[StairIndex].Floor + 1;
366			TSet<int32> Seen;
367			TArray<int32> Queue;
368			Seen.Add(StairIndex);
369			Queue.Add(StairIndex);
370			while (Queue.Num() > 0)
371			{
372				const FCL9ModulePlacement Module = Layout.Modules[Queue.Pop(EAllowShrinking::No)];
373				// 이 모듈이 위층에 없으면(다른 층의 계단 등) 거기서 멈춘다
374				if (Module.Floor > Upper || Module.TopFloor() < Upper)
375				{
376					continue;
377				}
378				for (int32 Side = 0; Side < 4; ++Side)
379				{
380					if (!(Module.Sockets & (1 << Side)))
381					{
382						continue;
383					}
384					const int32 Count = (Side == 0 || Side == 2) ? Module.Size.X : Module.Size.Y;
385					for (int32 Index = 0; Index < Count; ++Index)
386					{
387						FIntPoint Cell;
388						switch (Side)
389						{
390						case 0: Cell = FIntPoint(Module.Origin.X + Index, Module.Origin.Y + Module.Size.Y - 1); break;
391						case 2: Cell = FIntPoint(Module.Origin.X + Index, Module.Origin.Y); break;
392						case 1: Cell = FIntPoint(Module.Origin.X + Module.Size.X - 1, Module.Origin.Y + Index); break;
393						default: Cell = FIntPoint(Module.Origin.X, Module.Origin.Y + Index); break;
394						}
395						ECL9GridEdge Edge;
396						FIntPoint Next;
397						switch (Side)
398						{
399						case 1: Edge = Layout.EdgeAtX(Upper, Cell.X + 1, Cell.Y); Next = Cell + FIntPoint(1, 0); break;
400						case 3: Edge = Layout.EdgeAtX(Upper, Cell.X, Cell.Y); Next = Cell + FIntPoint(-1, 0); break;
401						case 0: Edge = Layout.EdgeAtY(Upper, Cell.X, Cell.Y + 1); Next = Cell + FIntPoint(0, 1); break;
402						default: Edge = Layout.EdgeAtY(Upper, Cell.X, Cell.Y); Next = Cell + FIntPoint(0, -1); break;
403						}
404						if (Edge != ECL9GridEdge::Door)
405						{
406							continue;
407						}
408						const int32 Other = Layout.CellAt(Upper, Next);
409						if (Other != INDEX_NONE && !Seen.Contains(Other))
410						{
411							Seen.Add(Other);
412							Queue.Add(Other);
413						}
414					}
415				}
416			}
417			return Seen.Num() - 1;
418		};
419	
420		for (uint32 Seed = 1; Seed <= 100; ++Seed)
421		{
422			const FCL9SiteLayout Layout = CL9SiteLayout::Generate(Params, Modules.Defs, Seed);
423			if (!Layout.bBuilt)
424			{
425				continue;
426			}
427			++Runs;
428			TwoOrMore += Layout.FloorCount >= 2 ? 1 : 0;
429			ThreeFloors += Layout.FloorCount >= 3 ? 1 : 0;
430	
431			if (!CL9SiteLayout::IsConnected(Layout))
432			{
433				++Disconnected;
434			}
435	
436			int32 Expected = 0;
437			for (const FCL9ModulePlacement& Module : Layout.Modules)
438			{
439				// 계단은 두 층을 차지하므로 칸을 두 번 센다
440				Expected += Module.Size.X * Module.Size.Y * (Module.TopFloor() - Module.Floor + 1);
441				Stairs += Module.bStairUp ? 1 : 0;
442				Upstairs += Module.Floor > 0 ? 1 : 0;
443	
444				// 계단을 올라가면 반드시 갈 데가 있어야 한다 (CL9SiteLayout::StairMinReach)
445				if (Module.bStairUp)
446				{
447					const int32 Reach = UpperReach(Layout, &Module - Layout.Modules.GetData());
448					ReachSum += Reach;
449					if (Reach < CL9SiteLayout::StairMinReach)
450					{
451						++Stranded;
452					}
453				}
454	
455				if (Module.TopFloor() >= Layout.FloorCount)
456				{
457					++Floating;
458				}
459				if (Module.Floor == 0)
460				{
461					continue;
462				}
463				// 위층 모듈은 아래층 실내 모듈이 빠짐없이 받쳐 줘야 한다
464				for (int32 Y = 0; Y < Module.Size.Y; ++Y)
465				{
466					for (int32 X = 0; X < Module.Size.X; ++X)
467					{
468						const int32 Below = Layout.CellAt(Module.Floor - 1, FIntPoint(Module.Origin.X + X, Module.Origin.Y + Y));
469						if (Below == INDEX_NONE || Layout.Modules[Below].Def->bOutdoor)
470						{
471							++Unsupported;
472						}
473					}
474				}
475			}
476			if (Expected != CountOccupiedCells(Layout))
477			{
478				++Overlapped;
479			}
480		}
481	
482		AddInfo(FString::Printf(TEXT("%d runs: %d reached 2 floors, %d reached 3. %.1f stairs and %.1f upstairs modules per run, %.1f rooms reachable above each stair."),
483			Runs, TwoOrMore, ThreeFloors, Stairs / FMath::Max(Runs, 1), Upstairs / FMath::Max(Runs, 1), ReachSum / FMath::Max(Stairs, 1.f)));
484		TestEqual(TEXT("no stair leads to a dead upper floor"), Stranded, 0);
485	
486		// 계단실은 위층 쪽에도 밟을 바닥이 있어야 한다 — 없으면 올라와서 디딤판 끝에 선 채로
487		// 어디로도 못 간다. 통로만 뚫려 있고 나머지는 덮여 있는지 본다.
488		{
489			const FCL9SiteLayout Layout = CL9SiteLayout::Generate(Params, Modules.Defs, 873);
490			TArray<FCL9SiteSeg> Segs;
491			CL9SiteLayout::BuildSegments(Params, Layout, Segs);
492	
493			int32 Checked = 0;
494			int32 Landless = 0;
495			for (const FCL9ModulePlacement& Module : Layout.Modules)
496			{
497				if (!Module.bStairUp)
498				{
499					continue;
500				}
501				++Checked;
502				const float UpperZ = (Module.Floor + 1) * Params.FloorHeight;
503				const FBox2D Rect(
504					Layout.Origin + FVector2D(Module.Origin.X * Params.CellSize, Module.Origin.Y * Params.CellSize),
505					Layout.Origin + FVector2D((Module.Origin.X + Module.Size.X) * Params.CellSize,
506						(Module.Origin.Y + Module.Size.Y) * Params.CellSize));
507	
508				float Covered = 0.f;
509				for (const FCL9SiteSeg& Seg : Segs)
510				{
511					if ((Seg.Kind != CL9SegKind::Floor() && Seg.Kind != CL9SegKind::Tread()) || !FMath::IsNearlyEqual(Seg.BaseZ, UpperZ, 1.f))
512					{
513						continue;
514					}
515					if (Rect.Intersect(Seg.Rect))
516					{
517						const FBox2D Overlap = Rect.Overlap(Seg.Rect);
518						Covered += Overlap.GetSize().X * Overlap.GetSize().Y;
519					}
520				}
521				// 통로만 뚫려 있으면 3분의 1은 덮여 있다 (양옆 띠 + 오르기 시작하는 쪽 참)
522				if (Covered < Rect.GetArea() * 0.3f)
523				{
524					++Landless;
525				}
526			}
527			TestTrue(TEXT("seed 873 has stairs to check"), Checked > 0);
528			TestEqual(TEXT("every stairwell has a landing to step off onto"), Landless, 0);
529		}
530	
531		TestEqual(TEXT("every module is reachable, floors included"), Disconnected, 0);
532		TestEqual(TEXT("no two modules share a cell on any floor"), Overlapped, 0);
533		TestEqual(TEXT("no upstairs cell hangs in the air"), Unsupported, 0);
534		TestEqual(TEXT("no module reaches past the top floor"), Floating, 0);
535		// 계단이 설 자리는 시드마다 다르지만, 대부분의 판은 2층까지 올라가야 한다
536		TestTrue(FString::Printf(TEXT("%d of %d runs reached a second floor"), TwoOrMore, Runs),
537			TwoOrMore >= Runs * 3 / 4);
538		return true;
539	}
540	
541	IMPLEMENT_SIMPLE_AUTOMATION_TEST(FCL9SiteLayoutLargeSiteTest,
542		"CL9.Map.LargeSite",
543		EAutomationTestFlags::EditorContext | EAutomationTestFlags::ProductFilter)
544	
545	bool FCL9SiteLayoutLargeSiteTest::RunTest(const FString& Parameters)
546	{
547		// 대농장(farm) 행과 같은 손잡이 — 양계장의 5배 판이 64칸 상한에 눌리지 않고 끝까지 서는지 본다 (2026-10-03)
548		const FTestModules Modules;
549		FCL9SiteParams Params;
550		Params.Theme = TEXT("henhouse");
551		Params.ModuleCount = 200;
552		Params.MaxFloors = 2;
553		Params.StairCountMin = 3;
554		Params.StairCountMax = 5;
555		Params.UpperFloorShare = 0.25f;
556		Params.LoopChance = 0.35f;
557		Params.MainPathShare = 0.3f;
558		Params.PassageShare = 0.4f;
559		Params.DeadEndShare = 0.3f;
560		Params.SpecialCopies = 4;
561	
562		int32 Disconnected = 0;
563		int32 Overlapped = 0;
564		int32 NoExit = 0;
565		int32 Unbuilt = 0;
566		int32 FewDeliveries = 0;
567		int32 Smallest = MAX_int32;
568		int32 SmallestGround = MAX_int32;
569		float Total = 0.f;
570		int32 Runs = 0;
571		const double Started = FPlatformTime::Seconds();
572	
573		for (uint32 Seed = 1; Seed <= 30; ++Seed)
574		{
575			const FCL9SiteLayout Layout = CL9SiteLayout::Generate(Params, Modules.Defs, Seed);
576			if (!Layout.bBuilt)
577			{
578				++Unbuilt;
579				continue;
580			}
581			Disconnected += CL9SiteLayout::IsConnected(Layout) ? 0 : 1;
582			int32 Expected = 0;
583			int32 Ground = 0;
584			for (const FCL9ModulePlacement& Module : Layout.Modules)
585			{
586				Expected += Module.Size.X * Module.Size.Y * (Module.bStairUp ? 2 : 1);
587				Ground += Module.Floor == 0 ? 1 : 0;
588			}
589			Overlapped += Expected != CountOccupiedCells(Layout) ? 1 : 0;
590			int32 Deliveries = 0;
591			for (const FCL9ModulePlacement& Module : Layout.Modules)
592			{
593				Deliveries += Module.Def->Alias == FName(TEXT("delivery")) ? 1 : 0;
594			}
595			FewDeliveries += Deliveries < 2 ? 1 : 0;
596			NoExit += CountEdges(Layout, ECL9GridEdge::Flap) != 1 ? 1 : 0;
597			Smallest = FMath::Min(Smallest, Layout.Modules.Num());
598			SmallestGround = FMath::Min(SmallestGround, Ground);
599			Total += Layout.Modules.Num();
600			++Runs;
601		}
602		const double Elapsed = FPlatformTime::Seconds() - Started;
603	
604		AddInfo(FString::Printf(TEXT("%d runs: smallest %d modules (ground %d of a wanted %d), avg %.1f, %.1f ms per layout."),
605			Runs, Smallest, SmallestGround, Params.ModuleCount, Total / FMath::Max(Runs, 1), 1000.0 * Elapsed / FMath::Max(Runs, 1)));
606	
607		TestEqual(TEXT("every seed builds"), Unbuilt, 0);
608		TestEqual(TEXT("every module is reachable through doors"), Disconnected, 0);
609		TestEqual(TEXT("no two modules share a cell"), Overlapped, 0);
610		TestEqual(TEXT("exactly one emergency exit per run"), NoExit, 0);
611		// SpecialCopies 4 — 납품 방(항아리)이 판에 여럿 서야 깊은 곳에서도 반납할 데가 있다
612		TestEqual(TEXT("runs with fewer than two delivery rooms"), FewDeliveries, 0);
613		// 5배 판이라 부른 이상 1층이 목표의 90%는 서야 한다
614		TestTrue(FString::Printf(TEXT("the smallest ground floor had %d modules of a wanted %d"), SmallestGround, Params.ModuleCount),
615			SmallestGround >= Params.ModuleCount * 9 / 10);
616		return true;
617	}
618	
619	IMPLEMENT_SIMPLE_AUTOMATION_TEST(FCL9SiteLayoutDepthBandTest,
620		"CL9.Map.DepthBand",
621		EAutomationTestFlags::EditorContext | EAutomationTestFlags::ProductFilter)
622	
623	bool FCL9SiteLayoutDepthBandTest::RunTest(const FString& Parameters)
624	{
625		// 구역 띠를 이어 붙이면 지점이 빠지지도 겹치지도 않아야 하고, 깊은 띠일수록 홉이 커야 한다
626		const FTestModules Modules;
627		FCL9SiteParams Params;
628		Params.Theme = TEXT("henhouse");
629		Params.ModuleCount = 200;
630		const FCL9SiteLayout Layout = CL9SiteLayout::Generate(Params, Modules.Defs, 873);
631		TestTrue(TEXT("seed 873 builds"), Layout.bBuilt);
632	
633		TArray<int32> All;
634		CL9SiteLayout::PointsOfPurpose(Layout, ECL9PointPurpose::Loot, All);
635		const float Edges[] = { 0.f, 0.35f, 0.7f, 1.f };
636		TArray<int32> Bands[3];
637		int32 Sum = 0;
638		for (int32 Band = 0; Band < 3; ++Band)
639		{
640			CL9SiteLayout::PointsInDepthBand(Layout, ECL9PointPurpose::Loot, Edges[Band], Edges[Band + 1], Bands[Band]);
641			Sum += Bands[Band].Num();
642			TestTrue(FString::Printf(TEXT("band %d has points"), Band), Bands[Band].Num() > 0);
643		}
644		TestEqual(TEXT("bands partition the loot points"), Sum, All.Num());
645	
646		auto MaxHops = [&Layout](const TArray<int32>& Indices)
647		{
648			int32 Hops = 0;
649			for (int32 Index : Indices)
650			{
651				Hops = FMath::Max(Hops, Layout.Points[Index].Hops);
652			}
653			return Hops;
654		};
655		TestTrue(TEXT("outer band is shallower than middle"), MaxHops(Bands[0]) <= MaxHops(Bands[1]));
656		TestTrue(TEXT("middle band is shallower than deep"), MaxHops(Bands[1]) <= MaxHops(Bands[2]));
657		return true;
658	}
659	
660	#endif
